def f(G):
    H=len(G); W=len(G[0])
    cnt={}
    for r in G:
        for x in r: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=lambda k:cnt[k])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if G[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; comp=set()
                while st:
                    y,x=st.pop()
                    if seen[y][x] or G[y][x]==bg: continue
                    seen[y][x]=True; comp.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx]:
                                st.append((ny,nx))
                comps.append(comp)
    big=max(comps,key=len)
    ys=[p[0] for p in big]; xs=[p[1] for p in big]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    sub=[[G[y][x] for x in range(x0,x1+1)] for y in range(y0,y1+1)]
    h,w=len(sub),len(sub[0])
    out=[r[:] for r in G]
    others=[c for c in comps if c!=big]
    pts=[(y,x,G[y][x]) for c in others for y,x in c]
    for y,x,v in pts:
        if x<x0 and y0<=y<=y1:  # noise left of obj in rows
            out[y][x0]=v
        elif y<y0 and x0<=x<=x1:
            out[y0][x]=v
        elif x>x1 and y0<=y<=y1:
            out[y][x1]=v
        elif y>y1 and x0<=x<=x1:
            out[y1][x]=v
        elif y<y0 and x<x0:      # top-left corner diag -> replace corner cell (y0,x0)?
            out[y0][x0]=v
        elif y>y1 and x>x1:
            out[y1][x1]=v
        elif y>y1 and x<x0:
            out[y1][x0]=v
        elif y<y0 and x>x1:
            out[y0][x1]=v
    return out
